-- ============================================================
-- STEP 1: HELPER FUNCTIONS IN public SCHEMA
-- ============================================================

-- Helper: get current user ID from session context safely
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  RETURN current_setting('app.current_user_id', true)::uuid;
EXCEPTION
  WHEN invalid_text_representation THEN
    RETURN NULL;
  WHEN others THEN
    RETURN NULL;
END;
$$;

-- Helper: check if a given user is the owner of a channel
CREATE OR REPLACE FUNCTION public.is_channel_owner(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL OR p_channel_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.channels c
    WHERE c.id = p_channel_id
      AND c.owner_id = p_user_id
  );
END;
$$;

-- Helper: check if a given user is a moderator of a channel
CREATE OR REPLACE FUNCTION public.is_channel_moderator(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL OR p_channel_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.channel_moderators cm
    WHERE cm.channel_id = p_channel_id
      AND cm.user_id = p_user_id
  );
END;
$$;

-- Helper: check if user can moderate a channel (owner OR moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_user_id IS NULL OR p_channel_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN (
    public.is_channel_owner(p_channel_id, p_user_id)
    OR
    public.is_channel_moderator(p_channel_id, p_user_id)
  );
END;
$$;

SELECT 'Helper functions created successfully' AS status;
"}

