-- ============================================================
-- STEP 3: USERS TABLE POLICIES
-- ============================================================

-- Drop any pre-existing policies first (idempotent)
DROP POLICY IF EXISTS "users_select_public_profiles"  ON public.users;
DROP POLICY IF EXISTS "users_update_own_profile"       ON public.users;
DROP POLICY IF EXISTS "users_delete_own_account"       ON public.users;

-- SELECT: Any visitor can read public profiles (is_public = true)
--         The profile owner can always read their own row
CREATE POLICY "users_select_public_profiles"
  ON public.users
  FOR SELECT
  USING (
    is_public = true
    OR id = public.current_user_id()
  );

-- UPDATE: Only the profile owner can update their own row
CREATE POLICY "users_update_own_profile"
  ON public.users
  FOR UPDATE
  USING (
    id = public.current_user_id()
  )
  WITH CHECK (
    id = public.current_user_id()
  );

-- DELETE: Only the account owner can delete their own account
CREATE POLICY "users_delete_own_account"
  ON public.users
  FOR DELETE
  USING (
    id = public.current_user_id()
  );

SELECT 'Users table policies created' AS status;
"}

