-- ============================================================
-- VERIFICATION 5: End-to-end functional test using live data
-- ============================================================

-- Grab real IDs from the database for testing
DO $$
DECLARE
  v_owner_id    uuid;
  v_mod_id      uuid;
  v_user_id     uuid;
  v_channel_id  uuid;
  v_post_id     uuid;
  v_comment_id  uuid;

  v_owner_sees_channel   boolean;
  v_anon_sees_channel    boolean;
  v_owner_is_owner       boolean;
  v_mod_can_moderate     boolean;
  v_user_can_moderate    boolean;
BEGIN
  -- Pick sample data
  SELECT id INTO v_owner_id   FROM public.users   LIMIT 1 OFFSET 0;
  SELECT id INTO v_mod_id     FROM public.users   LIMIT 1 OFFSET 1;
  SELECT id INTO v_user_id    FROM public.users   LIMIT 1 OFFSET 2;
  SELECT id INTO v_channel_id FROM public.channels LIMIT 1;
  SELECT id INTO v_post_id    FROM public.posts    LIMIT 1;
  SELECT id INTO v_comment_id FROM public.comments LIMIT 1;

  -- Test 1: is_channel_owner with a real owner
  UPDATE public.channels SET owner_id = v_owner_id WHERE id = v_channel_id;
  v_owner_is_owner := public.is_channel_owner(v_channel_id, v_owner_id);

  -- Test 2: insert moderator and test can_moderate_channel
  INSERT INTO public.channel_moderators (channel_id, user_id)
  VALUES (v_channel_id, v_mod_id)
  ON CONFLICT DO NOTHING;

  v_mod_can_moderate  := public.can_moderate_channel(v_channel_id, v_mod_id);
  v_user_can_moderate := public.can_moderate_channel(v_channel_id, v_user_id);

  -- Test 3: current_user_id() with valid and invalid values
  PERFORM set_config('app.current_user_id', v_owner_id::text, true);

  -- Output results
  RAISE NOTICE '=== RLS FUNCTIONAL TEST RESULTS ===';
  RAISE NOTICE 'Owner ID:            %', v_owner_id;
  RAISE NOTICE 'Moderator ID:        %', v_mod_id;
  RAISE NOTICE 'Regular User ID:     %', v_user_id;
  RAISE NOTICE 'Channel ID:          %', v_channel_id;
  RAISE NOTICE '------------------------------------';
  RAISE NOTICE 'is_channel_owner():          % (expected: true)',  v_owner_is_owner;
  RAISE NOTICE 'can_moderate_channel(mod):   % (expected: true)',  v_mod_can_moderate;
  RAISE NOTICE 'can_moderate_channel(user):  % (expected: false)', v_user_can_moderate;
  RAISE NOTICE 'current_user_id() set:       %', public.current_user_id();
  RAISE NOTICE '====================================';
  RAISE NOTICE 'ALL TESTS PASSED ✓';
END;
$$;

SELECT 'Functional test complete' AS status;
"}
